        current_intervals = [[a_start, a_end]]

        for b_start, b_end in b_normalized:
            next_intervals = []
            for curr_start, curr_end in current_intervals:
                # No overlap
                if curr_end <= b_start or curr_start >= b_end:
                    next_intervals.append([curr_start, curr_end])
                else:
                    # Partial or full overlap
                    if curr_start < b_start:
                        next_intervals.append([curr_start, b_start])
                    if curr_end > b_end:
